package ru.fifth.horror.block;
import net.minecraft.block.*;import net.minecraft.block.entity.BlockEntity;import net.minecraft.block.entity.BlockEntityTicker;import net.minecraft.block.entity.BlockEntityType;import net.minecraft.util.math.BlockPos;import org.jetbrains.annotations.Nullable;import ru.fifth.horror.FifthMod;import net.minecraft.block.BlockState;import net.minecraft.entity.player.PlayerEntity;import net.minecraft.text.Text;import net.minecraft.util.ActionResult;import net.minecraft.util.Hand;import net.minecraft.util.hit.BlockHitResult;import net.minecraft.world.World;
public final class TelevisionBlock extends BlockWithEntity{public TelevisionBlock(Settings s){super(s);}@Override public BlockEntity createBlockEntity(BlockPos p,BlockState s){return new TelevisionBlockEntity(p,s);}@Override public BlockRenderType getRenderType(BlockState s){return BlockRenderType.MODEL;}@Nullable @Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(World w,BlockState s,BlockEntityType<T> t){return w.isClient?checkType(t,FifthMod.TELEVISION_BE,TelevisionBlockEntity::tickClient):null;}@Override public ActionResult onUse(BlockState state,World world,net.minecraft.util.math.BlockPos pos,PlayerEntity player,Hand hand,BlockHitResult hit){if(!world.isClient)player.sendMessage(Text.literal("§8[§cFiven§8] §7Телевизор. Свяжи его с кассетоводом инструментом TV/VHS."),true);return ActionResult.success(world.isClient);}}
